from itertools import combinations
pieces=[]
for r in range(3):
 for c in range(6):
  sq={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  if sq<=cells: pieces.append((sq,1,'sq'))
for r in range(3):
 for c in range(6):
  box={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  for missing in box:
   shape=box-{missing}
   if shape<=cells:
    # IDs by missing relative loc
    ori=(missing[0]-r, missing[1]-c)
    col={(0,0):2,(1,0):3,(0,1):4,(1,1):5}[ori]
    pieces.append((shape,col,ori))
sol=[]
def solve(rem, chosen):
 if not rem:
  if len(chosen)==5 and sum(1 for _,col,_ in chosen if col==1)==1:sol.append(chosen)
  return
 x=min(rem)
 for p in pieces:
  sh,col,_=p
  if x in sh and sh<=rem:
   if col==1 and any(a==1 for _,a,_ in chosen):continue
   solve(rem-sh,chosen+[p])
solve(cells,[])
len(sol)
